import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { Card, Button, Form, ListGroup } from 'react-bootstrap';

const Gallery = () => {
  const [images, setImages] = useState([]);
  const [comment, setComment] = useState('');
  const [refresh, setRefresh] = useState(false);

  useEffect(() => {
    const fetchImages = async () => {
      try {
        const { data } = await axios.get('/api/gallery');
        setImages(data);
      } catch (error) {
        console.error('Error fetching images:', error);
      }
    };
    fetchImages();
  }, [refresh]);

  const handleLike = async (id) => {
    try {
      await axios.put(`/api/gallery/${id}/like`);
      setRefresh(!refresh);
    } catch (error) {
      console.error('Error liking image:', error);
    }
  };

  const handleUnlike = async (id) => {
    try {
      await axios.put(`/api/gallery/${id}/unlike`);
      setRefresh(!refresh);
    } catch (error) {
      console.error('Error unliking image:', error);
    }
  };

  const handleComment = async (id) => {
    if (!comment) return;
    try {
      await axios.post(`/api/gallery/${id}/comment`, { comment });
      setComment('');
      setRefresh(!refresh);
    } catch (error) {
      console.error('Error adding comment:', error);
    }
  };

  const handleDeleteComment = async (id, commentId) => {
    try {
      await axios.delete(`/api/gallery/${id}/comment/${commentId}`);
      setRefresh(!refresh);
    } catch (error) {
      console.error('Error deleting comment:', error);
    }
  };

  return (
    <div className="container mt-4">
      <h2>Gallery</h2>
      <div className="row">
        {images.map((image) => (
          <div key={image._id} className="col-md-4 mb-4">
            <Card>
              <Card.Img
                variant="top"
                src={image.imageUrl}
                alt="Gallery"
                style={{ height: '200px', objectFit: 'cover' }}
              />
              <Card.Body>
                <Card.Title>Uploaded by: {image.uploadedBy?.name}</Card.Title>
                <Card.Text>
                  <strong>Likes:</strong> {image.likes.length}
                </Card.Text>
                <Button
                  variant="success"
                  onClick={() => handleLike(image._id)}
                  className="me-2"
                >
                  Like
                </Button>
                <Button
                  variant="danger"
                  onClick={() => handleUnlike(image._id)}
                  className="me-2"
                >
                  Unlike
                </Button>
                <Form
                  onSubmit={(e) => {
                    e.preventDefault();
                    handleComment(image._id);
                  }}
                  className="mt-2"
                >
                  <Form.Group controlId="comment">
                    <Form.Control
                      type="text"
                      value={comment}
                      onChange={(e) => setComment(e.target.value)}
                      placeholder="Add a comment..."
                    />
                  </Form.Group>
                  <Button type="submit" className="mt-2" variant="primary">
                    Comment
                  </Button>
                </Form>
                <ListGroup className="mt-3">
                  {image.comments.map((c) => (
                    <ListGroup.Item key={c._id}>
                      <div className="d-flex justify-content-between">
                        <span>
                          <strong>{c.user?.name}:</strong> {c.comment}
                        </span>
                        <Button
                          variant="outline-danger"
                          size="sm"
                          onClick={() =>
                            handleDeleteComment(image._id, c._id)
                          }
                        >
                          Delete
                        </Button>
                      </div>
                    </ListGroup.Item>
                  ))}
                </ListGroup>
              </Card.Body>
            </Card>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Gallery;
